const q=new URLSearchParams(location.search),embedded=q.has('embedded'),select=document.querySelector('select'),frame=document.querySelector('.frame'),current=document.querySelector('.current'),incoming=document.querySelector('.incoming'),pause=document.querySelector('#pause');
const names={reveal:'Vertical image reveal',fade:'Image crossfade',push:'Horizontal image push'},images=['assets/react-bits/orbit.svg','assets/react-bits/studio.svg','assets/react-bits/landscape.svg'],alts=['Orbital sculpture','Architectural composition','Sunlit landscape'];
let mode=q.get('demo')?.replace('im-','')||'reveal',index=0,target=0,busy=false,paused=q.has('paused'),animations=[];if(!names[mode])mode='reveal';select.value=mode;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');document.body.classList.toggle('embedded',embedded);document.querySelector('.hint').textContent=embedded?'FIXED FRAME / ENTRY + EXIT':'SCROLL TO CHANGE IMAGE';
const ready=Promise.all(images.map(src=>{const img=new Image();img.src=src;return img.decode().catch(()=>{});}));
function labels(){document.querySelector('#name').textContent=names[mode];document.querySelector('#count').textContent='0'+(index+1)+' / 03';frame.setAttribute('aria-label',alts[index]);document.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.slide)===index));pause.textContent=paused?'Resume motion':'Pause motion';}
async function change(next){target=next;if(busy||next===index)return;busy=true;await ready;const destination=target,dir=destination>index?1:-1;incoming.src=images[destination];await incoming.decode().catch(()=>{});incoming.style.visibility='visible';
const options={duration:paused||reduced.matches?0:850,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'};
let enter,exit;if(mode==='reveal'){enter=[{transform:`translateY(${dir*100}%)`},{transform:'translateY(0)'}];exit=[{transform:'translateY(0)'},{transform:`translateY(${-dir*18}%)`}];}else if(mode==='fade'){enter=[{opacity:0,transform:'scale(1.045)'},{opacity:1,transform:'scale(1)'}];exit=[{transform:'scale(1)'},{transform:'scale(1.015)'}];}else{enter=[{transform:`translateX(${dir*100}%)`},{transform:'translateX(0)'}];exit=[{transform:'translateX(0)'},{transform:`translateX(${-dir*100}%)`}];}
animations=[incoming.animate(enter,options),current.animate(exit,options)];await Promise.all(animations.map(a=>a.finished.catch(()=>{})));current.src=images[destination];await current.decode().catch(()=>{});incoming.style.visibility='hidden';animations.forEach(a=>a.cancel());animations=[];index=destination;labels();busy=false;if(target!==index)change(target);}
select.addEventListener('change',()=>{mode=select.value;labels();});document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.slide);if(embedded)change(i);else window.scrollTo({top:i/2*(document.documentElement.scrollHeight-innerHeight),behavior:reduced.matches?'instant':'smooth'});}));
function setPaused(value){paused=value;if(paused)animations.forEach(a=>a.finish());labels();}pause.onclick=()=>setPaused(!paused);window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='atlas-motion')setPaused(e.data.paused);});reduced.addEventListener('change',()=>{if(reduced.matches)animations.forEach(a=>a.finish());});
if(embedded)setInterval(()=>{if(!paused&&!reduced.matches&&!document.hidden&&!busy)change((index+1)%3);},3500);else window.addEventListener('scroll',()=>change(Math.min(2,Math.round(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*2))),{passive:true});labels();ready.then(()=>{if(embedded)parent.postMessage({type:'atlas-preview-ready'},location.origin);});
